            self.weight.data_ptr(),
            out.data_ptr(),
            batch,
            self.in_channels,
            self.out_channels,
            length,
            self.kernel_size,
            self.stride,
            self.dilation,
            length_out
        ]

        ptx_launch(self.module, "conv1d_fp16", grid, block, args)
